  1	package com.pousada.marealta;
  2	
  3	import com.google.gson.Gson;
  4	import com.google.gson.GsonBuilder;
  5	import com.pousada.marealta.api.ErrorResponse;
  6	import com.pousada.marealta.db.Database;
  7	import com.pousada.marealta.db.RoomRepository;
  8	import com.pousada.marealta.db.ReservationRepository;
  9	import com.pousada.marealta.db.MessageRepository;
 10	import com.pousada.marealta.model.*;
 11	import com.pousada.marealta.service.DocumentService;
 12	import com.pousada.marealta.service.MessageService;
 13	import com.pousada.marealta.service.ReportService;
 14	import com.pousada.marealta.service.ReservationService;
 15	import io.javalin.Javalin;
 16	import io.javalin.http.Context;
 17	import io.javalin.http.HttpStatus;
 18	
 19	import java.math.BigDecimal;
 20	import java.time.LocalDate;
 21	import java.time.format.DateTimeFormatter;
 22	import java.util.List;
 23	import java.util.HashMap;
 24	import java.util.Map;
 25	
 26	public class Application {
 27	    private static final Gson gson = new GsonBuilder()
 28	            .create();
 29	    private static final DateTimeFormatter dateFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd");
 30	
 31	    public static void main(String[] args) throws Exception {
 32	        Database.initialize();
 33	
 34	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
 35	        Javalin app = Javalin.create().start(port);
 36	
 37	        app.get("/rooms", ctx -> {
 38	            try {
 39	                List<Room> rooms = RoomRepository.findAll();
 40	                ctx.json(rooms.stream().map(r -> Map.of(
 41	                        "number", r.number,
 42	                        "type", r.type.name(),
 43	                        "capacity", r.capacity,
 44	                        "nightlyRate", r.nightlyRate.doubleValue()
 45	                )).toList());
 46	            } catch (Exception e) {
 47	                ctx.status(HttpStatus.INTERNAL_SERVER_ERROR);
 48	                ctx.json(new ErrorResponse("INTERNAL_ERROR", e.getMessage()));
 49	            }
 50	        });
 51	
 52	        app.post("/reservations", ctx -> {
 53	            try {
 54	                Map<String, Object> body = gson.fromJson(ctx.body(), Map.class);
 55	                validateRequiredFields(body, "roomNumber", "guestName", "guestEmail", "guestCpf", "checkIn", "checkOut", "guests", "ratePlan");
 56	
 57	                int roomNumber = ((Double) body.get("roomNumber")).intValue();
 58	                String guestName = (String) body.get("guestName");
 59	                String guestEmail = (String) body.get("guestEmail");
 60	                String guestCpf = (String) body.get("guestCpf");
 61	                LocalDate checkIn = LocalDate.parse((String) body.get("checkIn"), dateFormatter);
 62	                LocalDate checkOut = LocalDate.parse((String) body.get("checkOut"), dateFormatter);
 63	                int guests = ((Double) body.get("guests")).intValue();
 64	                RatePlan ratePlan = RatePlan.valueOf((String) body.get("ratePlan"));
 65	
 66	                if (checkOut.isBefore(checkIn) || checkOut.equals(checkIn)) {
 67	                    ctx.status(HttpStatus.BAD_REQUEST);
 68	                    ctx.json(new ErrorResponse("INVALID_REQUEST", "Check-out must be after check-in"));
 69	                    return;
 70	                }
 71	
 72	                Reservation reservation = ReservationService.createReservation(roomNumber, guestName, guestEmail, guestCpf, checkIn, checkOut, guests, ratePlan);
 73	                ctx.status(HttpStatus.CREATED);
 74	                ctx.json(reservationToJson(reservation));
 75	            } catch (IllegalArgumentException e) {
 76	                handleError(ctx, e.getMessage());
 77	            } catch (Exception e) {
 78	                ctx.status(HttpStatus.BAD_REQUEST);
 79	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Invalid request format"));
 80	            }
 81	        });
 82	
 83	        app.get("/reservations/:id", ctx -> {
 84	            try {
 85	                long id = Long.parseLong(ctx.pathParam("id"));
 86	                Reservation reservation = ReservationRepository.findById(id);
 87	                if (reservation == null) {
 88	                    ctx.status(HttpStatus.NOT_FOUND);
 89	                    ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
 90	                    return;
 91	                }
 92	                ctx.json(reservationToJson(reservation));
 93	            } catch (NumberFormatException e) {
 94	                ctx.status(HttpStatus.BAD_REQUEST);
 95	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
 96	            }
 97	        });
 98	
 99	        app.post("/reservations/:id/confirmation", ctx -> {
100	            try {
101	                long id = Long.parseLong(ctx.pathParam("id"));
102	                Map<String, Object> body = gson.fromJson(ctx.body(), Map.class);
103	                BigDecimal amountPaid = new BigDecimal(body.get("amountPaid").toString());
104	
105	                Reservation reservation = ReservationService.confirmReservation(id, amountPaid);
106	                ctx.json(reservationToJson(reservation));
107	            } catch (IllegalArgumentException e) {
108	                handleError(ctx, e.getMessage());
109	            } catch (Exception e) {
110	                ctx.status(HttpStatus.BAD_REQUEST);
111	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Invalid request format"));
112	            }
113	        });
114	
115	        app.post("/reservations/:id/cancellation", ctx -> {
116	            try {
117	                long id = Long.parseLong(ctx.pathParam("id"));
118	                Reservation reservation = ReservationService.cancelReservation(id);
119	                ctx.json(reservationToJson(reservation));
120	            } catch (IllegalArgumentException e) {
121	                handleError(ctx, e.getMessage());
122	            } catch (Exception e) {
123	                ctx.status(HttpStatus.INTERNAL_SERVER_ERROR);
124	                ctx.json(new ErrorResponse("INTERNAL_ERROR", e.getMessage()));
125	            }
126	        });
127	
128	        app.post("/reservations/:id/check-in", ctx -> {
129	            try {
130	                long id = Long.parseLong(ctx.pathParam("id"));
131	                Reservation reservation = ReservationService.checkIn(id);
132	                ctx.json(reservationToJson(reservation));
133	            } catch (IllegalArgumentException e) {
134	                handleError(ctx, e.getMessage());
135	            } catch (Exception e) {
136	                ctx.status(HttpStatus.INTERNAL_SERVER_ERROR);
137	                ctx.json(new ErrorResponse("INTERNAL_ERROR", e.getMessage()));
138	            }
139	        });
140	
141	        app.post("/reservations/:id/check-out", ctx -> {
142	            try {
143	                long id = Long.parseLong(ctx.pathParam("id"));
144	                Reservation reservation = ReservationService.checkOut(id);
145	                Room room = RoomRepository.findByNumber(reservation.roomNumber);
146	                Document document = new Document(reservation.id, reservation.guestName, reservation.guestCpf,
147	                        reservation.roomNumber, room.type.name(), reservation.checkIn, reservation.checkOut,
148	                        reservation.nights, reservation.subtotal, reservation.discount, reservation.total);
149	                ctx.json(documentToJson(document));
150	            } catch (IllegalArgumentException e) {
151	                handleError(ctx, e.getMessage());
152	            } catch (Exception e) {
153	                ctx.status(HttpStatus.INTERNAL_SERVER_ERROR);
154	                ctx.json(new ErrorResponse("INTERNAL_ERROR", e.getMessage()));
155	            }
156	        });
157	
158	        app.get("/reservations/:id/document", ctx -> {
159	            try {
160	                long id = Long.parseLong(ctx.pathParam("id"));
161	                Reservation reservation = ReservationRepository.findById(id);
162	                if (reservation == null) {
163	                    ctx.status(HttpStatus.NOT_FOUND);
164	                    ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
165	                    return;
166	                }
167	
168	                if (reservation.amountPaid.compareTo(BigDecimal.ZERO) <= 0) {
169	                    ctx.status(HttpStatus.NOT_FOUND);
170	                    ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Document not available for unpaid reservations"));
171	                    return;
172	                }
173	
174	                Room room = RoomRepository.findByNumber(reservation.roomNumber);
175	                Document document = new Document(reservation.id, reservation.guestName, reservation.guestCpf,
176	                        reservation.roomNumber, room.type.name(), reservation.checkIn, reservation.checkOut,
177	                        reservation.nights, reservation.subtotal, reservation.discount, reservation.total);
178	                ctx.json(documentToJson(document));
179	            } catch (NumberFormatException e) {
180	                ctx.status(HttpStatus.BAD_REQUEST);
181	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
182	            }
183	        });
184	
185	        app.get("/messages", ctx -> {
186	            try {
187	                List<Message> messages = MessageService.getAllMessages();
188	                ctx.json(messages.stream().map(m -> Map.of(
189	                        "id", m.id,
190	                        "channel", m.channel,
191	                        "to", m.to,
192	                        "subject", m.subject,
193	                        "body", m.body,
194	                        "status", m.status.name()
195	                )).toList());
196	            } catch (Exception e) {
197	                ctx.status(HttpStatus.INTERNAL_SERVER_ERROR);
198	                ctx.json(new ErrorResponse("INTERNAL_ERROR", e.getMessage()));
199	            }
200	        });
201	
202	        app.get("/reports/occupancy", ctx -> {
203	            try {
204	                String dateStr = ctx.queryParam("date");
205	                if (dateStr == null) {
206	                    ctx.status(HttpStatus.BAD_REQUEST);
207	                    ctx.json(new ErrorResponse("INVALID_REQUEST", "Date parameter required"));
208	                    return;
209	                }
210	                LocalDate date = LocalDate.parse(dateStr, dateFormatter);
211	                String report = ReportService.generateOccupancyReport(date);
212	                ctx.contentType("text/csv;charset=utf-8");
213	                ctx.result(report);
214	            } catch (Exception e) {
215	                ctx.status(HttpStatus.BAD_REQUEST);
216	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Invalid date format"));
217	            }
218	        });
219	
220	        app.get("/reports/revenue", ctx -> {
221	            try {
222	                String monthStr = ctx.queryParam("month");
223	                if (monthStr == null) {
224	                    ctx.status(HttpStatus.BAD_REQUEST);
225	                    ctx.json(new ErrorResponse("INVALID_REQUEST", "Month parameter required"));
226	                    return;
227	                }
228	                String[] parts = monthStr.split("-");
229	                int year = Integer.parseInt(parts[0]);
230	                int month = Integer.parseInt(parts[1]);
231	                String report = ReportService.generateRevenueReport(year, month);
232	                ctx.contentType("text/csv;charset=utf-8");
233	                ctx.result(report);
234	            } catch (Exception e) {
235	                ctx.status(HttpStatus.BAD_REQUEST);
236	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Invalid month format"));
237	            }
238	        });
239	
240	        app.exception(Exception.class, (e, ctx) -> {
241	            ctx.status(HttpStatus.INTERNAL_SERVER_ERROR);
242	            ctx.json(new ErrorResponse("INTERNAL_ERROR", e.getMessage()));
243	        });
244	    }
245	
246	    private static void validateRequiredFields(Map<String, Object> body, String... fields) throws Exception {
247	        for (String field : fields) {
248	            if (body.get(field) == null) {
249	                throw new IllegalArgumentException("INVALID_REQUEST");
250	            }
251	        }
252	    }
253	
254	    private static void handleError(Context ctx, String errorCode) {
255	        switch (errorCode) {
256	            case "ROOM_NOT_FOUND":
257	                ctx.status(HttpStatus.NOT_FOUND);
258	                ctx.json(new ErrorResponse("ROOM_NOT_FOUND", "Room not found"));
259	                break;
260	            case "RESERVATION_NOT_FOUND":
261	                ctx.status(HttpStatus.NOT_FOUND);
262	                ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
263	                break;
264	            case "ROOM_UNAVAILABLE":
265	                ctx.status(HttpStatus.CONFLICT);
266	                ctx.json(new ErrorResponse("ROOM_UNAVAILABLE", "Room is not available for these dates"));
267	                break;
268	            case "CAPACITY_EXCEEDED":
269	                ctx.status(422);
270	                ctx.json(new ErrorResponse("CAPACITY_EXCEEDED", "Number of guests exceeds room capacity"));
271	                break;
272	            case "OPERATION_NOT_ALLOWED":
273	                ctx.status(HttpStatus.CONFLICT);
274	                ctx.json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Operation not allowed in current reservation status"));
275	                break;
276	            default:
277	                ctx.status(HttpStatus.BAD_REQUEST);
278	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Invalid request"));
279	        }
280	    }
281	
282	    private static Map<String, Object> reservationToJson(Reservation r) {
283	        Map<String, Object> map = new HashMap<>();
284	        map.put("id", r.id);
285	        map.put("roomNumber", r.roomNumber);
286	        map.put("guestName", r.guestName);
287	        map.put("guestEmail", r.guestEmail);
288	        map.put("guestCpf", r.guestCpf);
289	        map.put("checkIn", r.checkIn.toString());
290	        map.put("checkOut", r.checkOut.toString());
291	        map.put("guests", r.guests);
292	        map.put("ratePlan", r.ratePlan.name());
293	        map.put("nights", r.nights);
294	        map.put("subtotal", r.subtotal.doubleValue());
295	        map.put("discount", r.discount.doubleValue());
296	        map.put("total", r.total.doubleValue());
297	        map.put("status", r.status.name());
298	        map.put("amountPaid", r.amountPaid.doubleValue());
299	        map.put("refund", r.refund != null ? r.refund.doubleValue() : null);
300	        return map;
301	    }
302	
303	    private static Map<String, Object> documentToJson(Document d) {
304	        Map<String, Object> map = new HashMap<>();
305	        map.put("title", d.title);
306	        map.put("reservationId", d.reservationId);
307	        map.put("guestName", d.guestName);
308	        map.put("guestCpf", d.guestCpf);
309	        map.put("roomNumber", d.roomNumber);
310	        map.put("roomType", d.roomType);
311	        map.put("checkIn", d.checkIn.toString());
312	        map.put("checkOut", d.checkOut.toString());
313	        map.put("nights", d.nights);
314	        map.put("subtotal", d.subtotal.doubleValue());
315	        map.put("discount", d.discount.doubleValue());
316	        map.put("total", d.total.doubleValue());
317	        return map;
318	    }
319	}
