254	    private static void handleError(Context ctx, String errorCode) {
255	        switch (errorCode) {
256	            case "ROOM_NOT_FOUND":
257	                ctx.status(HttpStatus.NOT_FOUND);
258	                ctx.json(new ErrorResponse("ROOM_NOT_FOUND", "Room not found"));
259	                break;
