    13	public class ReportService {
    14	    public static String generateOccupancyReport(LocalDate date) throws Exception {
    15	        List<Reservation> reservations = ReservationRepository.findByDateAndStatus(date, ReservationStatus.CONFIRMED);
    16	        List<Reservation> checkedIn = ReservationRepository.findByDateAndStatus(date, ReservationStatus.CHECKED_IN);
    17	        List<Reservation> checkedOut = ReservationRepository.findByDateAndStatus(date, ReservationStatus.CHECKED_OUT);
    18	
    19	        reservations.addAll(checkedIn);
    20	        reservations.addAll(checkedOut);
    21	
    22	        StringBuilder csv = new StringBuilder("room,type,reservation,check_in,check_out\n");
    23	
    24	        int occupiedCount = 0;
    25	        for (Reservation res : reservations) {
    26	            Room room = RoomRepository.findByNumber(res.roomNumber);
    27	            csv.append(res.roomNumber).append(",")
    28	                    .append(room.type).append(",")
    29	                    .append(res.id).append(",")
    30	                    .append(formatDate(res.checkIn)).append(",")
    31	                    .append(formatDate(res.checkOut)).append("\n");
    32	            occupiedCount++;
    33	        }
    34	
    35	        List<Room> allRooms = RoomRepository.findAll();
    36	        csv.append("total,").append(occupiedCount).append("/").append(allRooms.size());
    37	
    38	        return csv.toString();
    39	    }
    40	
    41	    public static String generateRevenueReport(int year, int month) throws Exception {
    42	        List<Reservation> reservations = ReservationRepository.findByMonthAndStatus(year, month, null);
    43	
    44	        StringBuilder csv = new StringBuilder("reservation,room,check_in,check_out,status,amount\n");
    45	        BigDecimal totalAmount = BigDecimal.ZERO;
    46	
    47	        for (Reservation res : reservations) {
    48	            BigDecimal amount = res.amountPaid;
    49	            if (res.status == ReservationStatus.CANCELLED && res.refund != null) {
    50	                amount = res.amountPaid.subtract(res.refund);
    51	            }
    52	
    53	            csv.append(res.id).append(",")
    54	                    .append(res.roomNumber).append(",")
    55	                    .append(formatDate(res.checkIn)).append(",")
    56	                    .append(formatDate(res.checkOut)).append(",")
    57	                    .append(res.status).append(",")
    58	                    .append(formatMoney(amount)).append("\n");
    59	
    60	            totalAmount = totalAmount.add(amount);
    61	        }
    62	
    63	        csv.append("total,,,,").append(formatMoney(totalAmount));
    64	
    65	        return csv.toString();
    66	    }
    67	
    68	    private static String formatDate(LocalDate date) {
    69	        return String.format("%04d-%02d-%02d", date.getYear(), date.getMonthValue(), date.getDayOfMonth());
    70	    }
    71	
    72	    private static String formatMoney(BigDecimal value) {
    73	        return String.format("%.2f", value).replace(",", ".");
    74	    }
    75	}
