     8	import java.math.BigDecimal;
     9	import java.time.LocalDate;
    10	
    11	public class ReservationService {
    12	    public static Reservation createReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
    13	                                                LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) throws Exception {
    14	        Room room = RoomRepository.findByNumber(roomNumber);
    15	        if (room == null) {
    16	            throw new IllegalArgumentException("ROOM_NOT_FOUND");
    17	        }
    18	
    19	        if (guests < 1 || guests > room.capacity) {
    20	            throw new IllegalArgumentException(guests > room.capacity ? "CAPACITY_EXCEEDED" : "INVALID_REQUEST");
    21	        }
    22	
    23	        if (checkIn.isAfter(checkOut) || checkIn.equals(checkOut)) {
    24	            throw new IllegalArgumentException("INVALID_REQUEST");
    25	        }
    26	
    27	        if (!ReservationRepository.isRoomAvailable(roomNumber, checkIn, checkOut)) {
    28	            throw new IllegalArgumentException("ROOM_UNAVAILABLE");
    29	        }
    30	
    31	        int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
    32	        BigDecimal subtotal = BigDecimal.ZERO;
    33	
    34	        for (LocalDate date = checkIn; date.isBefore(checkOut); date = date.plusDays(1)) {
    35	            BigDecimal nightlyPrice = PriceCalculator.calculateNightlyPrice(room.nightlyRate, date);
    36	            subtotal = subtotal.add(nightlyPrice);
    37	        }
    38	        subtotal = PriceCalculator.roundPrice(subtotal);
    39	
    40	        BigDecimal discount = PriceCalculator.calculateDiscount(subtotal, ratePlan.name());
    41	        BigDecimal total = PriceCalculator.calculateTotal(subtotal, discount);
    42	
    43	        return ReservationRepository.create(roomNumber, guestName, guestEmail, guestCpf, checkIn, checkOut,
    44	                guests, ratePlan, nights, subtotal, discount, total);
    45	    }
    46	
    47	    public static Reservation confirmReservation(long reservationId, BigDecimal amountPaid) throws Exception {
    48	        Reservation reservation = ReservationRepository.findById(reservationId);
    49	        if (reservation == null) {
    50	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
    51	        }
    52	
    53	        if (reservation.status != ReservationStatus.PENDING) {
    54	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
    55	        }
    56	
    57	        ReservationRepository.updateStatusAndAmountPaid(reservationId, ReservationStatus.CONFIRMED, amountPaid);
    58	
    59	        sendConfirmationEmail(reservation);
    60	
    61	        return ReservationRepository.findById(reservationId);
    62	    }
    63	
    64	    public static Reservation checkIn(long reservationId) throws Exception {
    65	        Reservation reservation = ReservationRepository.findById(reservationId);
    66	        if (reservation == null) {
    67	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
    68	        }
    69	
    70	        if (reservation.status != ReservationStatus.CONFIRMED) {
    71	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
    72	        }
    73	
    74	        ReservationRepository.updateStatus(reservationId, ReservationStatus.CHECKED_IN);
    75	        return ReservationRepository.findById(reservationId);
    76	    }
    77	
    78	    public static Reservation checkOut(long reservationId) throws Exception {
    79	        Reservation reservation = ReservationRepository.findById(reservationId);
    80	        if (reservation == null) {
    81	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
    82	        }
    83	
    84	        if (reservation.status != ReservationStatus.CHECKED_IN) {
    85	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
    86	        }
    87	
    88	        ReservationRepository.updateStatus(reservationId, ReservationStatus.CHECKED_OUT);
    89	        return ReservationRepository.findById(reservationId);
    90	    }
    91	
    92	    public static Reservation cancelReservation(long reservationId) throws Exception {
    93	        Reservation reservation = ReservationRepository.findById(reservationId);
    94	        if (reservation == null) {
    95	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
    96	        }
    97	
    98	        if (reservation.status != ReservationStatus.PENDING && reservation.status != ReservationStatus.CONFIRMED) {
    99	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
   100	        }
   101	
   102	        BigDecimal refund;
   103	        if (reservation.ratePlan == RatePlan.STANDARD && reservation.status == ReservationStatus.CONFIRMED) {
   104	            refund = reservation.amountPaid;
   105	        } else {
   106	            refund = BigDecimal.ZERO;
   107	        }
   108	
   109	        ReservationRepository.updateStatusAndRefund(reservationId, ReservationStatus.CANCELLED, refund);
   110	        return ReservationRepository.findById(reservationId);
   111	    }
   112	
   113	    private static void sendConfirmationEmail(Reservation reservation) throws Exception {
   114	        Room room = RoomRepository.findByNumber(reservation.roomNumber);
   115	        String subject = "Reserva confirmada - Pousada Maré Alta";
   116	        String body = buildConfirmationEmailBody(reservation, room);
   117	        MessageService.sendMessage(reservation.guestEmail, subject, body);
   118	    }
   119	
   120	    private static String buildConfirmationEmailBody(Reservation reservation, Room room) {
   121	        String document = DocumentService.buildDocument(reservation, room);
   122	        return String.format("Olá, %s!\n\n" +
   123	                        "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n" +
   124	                        "%s\n\n" +
   125	                        "A entrada é a partir das 14h, e a saída, até as 12h.\n" +
   126	                        "Até breve!",
   127	                reservation.guestName, document);
   128	    }
   129	}
